// This repo's scripts, read from package.json rather than remembered.
import { REPO_ROOT } from "../_shared/deno-helpers.ts";

const pkg = JSON.parse(await Deno.readTextFile(`${REPO_ROOT}/package.json`));

for (const [name, cmd] of Object.entries(pkg.scripts)) {
  console.log(`npm run ${name.padEnd(16)} -> ${cmd}`);
}

// Before installing anything: does this machine meet Jenkins' requirements?
async function probe(cmd: string, args: string[]): Promise<string> {
  try {
    const c = new Deno.Command(cmd, { args, stdout: "piped", stderr: "piped" });
    const o = await c.output();
    const t = new TextDecoder().decode(o.stdout) + new TextDecoder().decode(o.stderr);
    return t.trim().split("|")[0].split(String.fromCharCode(10))[0];
  } catch {
    return "(not installed)";
  }
}

console.log("java :", await probe("java", ["-version"]));
console.log("node :", await probe("node", ["--version"]));

// Is Jenkins already answering on its default port?
try {
  const res = await fetch("http://localhost:8080", {
    signal: AbortSignal.timeout(3000),
  });
  console.log("jenkins on :8080 -> HTTP", res.status);
} catch {
  console.log("jenkins on :8080 -> not running (expected, if you have not installed it)");
}

import { writeProjectFile, REPO_ROOT } from "../_shared/deno-helpers.ts";

// The same commands a Jenkins build step runs - minus npm ci.

// Backslashes before ` and ${ because the file sits inside a template literal.

await writeProjectFile("week6/generated/day4-ci-commands.ts", `// Week 6, Day 4 — the commands a Jenkins job actually runs, run here.
//
// Jenkins itself is a web UI you click; that part cannot be verified by a script.
// What CAN be verified is the batch command you paste into it, and that is the part
// that fails for real people. So this runs the sequence locally.
//
//   deno run -A week6/generated/day4-ci-commands.ts
//
// Written by a cell in week6/day4_2.ipynb.

const NPX = Deno.build.os === "windows" ? "npx.cmd" : "npx";
const NPM = Deno.build.os === "windows" ? "npm.cmd" : "npm";

async function step(label: string, cmd: string, args: string[]): Promise<boolean> {
  console.log(\`\\n--- \${label} ---\`);
  console.log(\`$ \${cmd === NPX ? "npx" : "npm"} \${args.join(" ")}\`);
  const t0 = performance.now();
  const p = new Deno.Command(cmd, { args, stdout: "piped", stderr: "piped" });
  const { code, stdout, stderr } = await p.output();
  const out = new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr);
  const ms = Math.round(performance.now() - t0);
  const tail = out.trim().split("\\n").slice(-3).map((l) => "  " + l.trim()).join("\\n");
  console.log(tail);
  console.log(\`  -> exit \${code} in \${ms} ms\`);
  return code === 0;
}

console.log("A Jenkins build step is just these lines, in order.\\n");

console.log("=== 1. npm ci — SKIPPED, deliberately ===");
console.log("  npm ci DELETES node_modules and rebuilds it from package-lock.json.");
console.log("  That is right for a fresh CI agent and wrong for your working copy,");
console.log("  so this script does not run it. On a Jenkins agent it is step one.");
console.log("  Why \`npm ci\` and not \`npm install\`: ci installs the EXACT locked");
console.log("  versions and fails if the lockfile disagrees with package.json.");

console.log("\\n=== 2. npx playwright install --with-deps ===");
console.log("  Downloads the browser binaries. A fresh agent has none, which is the");
console.log("  real cause of 'Executable doesn't exist' on a first Jenkins build.");
console.log("  Already present here, so we only prove the CLI answers:");
await step("playwright version", NPX, ["playwright", "--version"]);

console.log("\\n=== 3. npm run <suite> — the actual test run ===");
const ok = await step("smoke suite", NPM, ["run", "test:smoke", "--silent"]);

console.log("\\n=== What Jenkins does with that exit code ===");
console.log(\`  smoke suite exit 0? \${ok}\`);
console.log("  Exit 0 -> build goes green. Non-zero -> red. That is the entire");
console.log("  contract between your tests and any CI tool: the exit code.");
`);

// Run it the way you would from a terminal.
const proc = new Deno.Command("deno", {
  args: ["run", "-A", "week6/generated/day4-ci-commands.ts"],
  cwd: REPO_ROOT,
  stdout: "piped",
  stderr: "piped",
});
const { stdout, stderr } = await proc.output();
console.log(new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr));

// Prove the two names really select different suites.
import { REPO_ROOT } from "../_shared/deno-helpers.ts";

const results: Record<string, string> = {};

for (const script of ["test:smoke", "test:regression"]) {
  const proc = new Deno.Command(Deno.build.os === "windows" ? "npm.cmd" : "npm", {
    args: ["run", script, "--silent"],
    cwd: REPO_ROOT,
    stdout: "piped",
    stderr: "piped",
  });
  const { stdout, stderr } = await proc.output();
  const text = new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr);
  results[script] = text.split("\n").filter((l) => /passed|failed/.test(l)).pop()?.trim() ?? "?";
}

for (const [k, v] of Object.entries(results)) console.log(`npm run ${k.padEnd(16)} -> ${v}`);
